"responseType": "choice",
"question": "Which of the following polynomials is a perfect square?",
"questionType": "text",
"choices": {
"A": "\\(x^2+2x-1\\)",
"B": "\\(x^2+4x+16\\)",
"C": "\\(x^2-4x+4\\)",
"D": "\\(x^2+x+1\\)"
},
