"responseType": "choice",
"question": "How can the mean be estimated from grouped data?",
"questionType": "text",
"choices": {
"A": "Add the class midpoints and divide by the number of classes.",
"B": "Add the class frequencies and divide by the number of classes.",
"C": "Multiply each class's upper limit by its frequency, add the products, and divide by the total frequency.",
"D": "Multiply each class midpoint by its frequency, add the products, and divide by the total frequency."
},
